function validate([total, cost1, cost2]) {
  for (const [name, value] of [['total', total], ['cost1', cost1], ['cost2', cost2]]) {
    if (!Number.isInteger(value) || value < 1 || value > 1000000) return name + ' is an integer from 1 to 10^6.';
  }
  return null;
}

