function waysToBuyPensPencils(total, cost1, cost2) {
  let ways = 0;
  for (let pens = 0; pens * cost1 <= total; pens++) {
    const spent = pens * cost1;
    const remaining = total - spent;
    const maxPencils = Math.floor(remaining / cost2);
    ways += maxPencils + 1;
  }
  return ways;
}

