function waysToBuyPensPencils(total, cost1, cost2) {
  let count = 0;
  for (let a = 0; a * cost1 <= total; a++) {
    for (let b = 0; a * cost1 + b * cost2 <= total; b++) {
      count++;
    }
  }
  return count;
}

