function generate(rand, size) {
  if (size === 'large') {
    const total = 1000000 - Math.floor(rand() * 100000);
    const pick = () => (rand() < 0.5 ? 1 + Math.floor(rand() * 10) : 1 + Math.floor(rand() * 1000));
    return [total, pick(), pick()];
  }
  const total = 1 + Math.floor(rand() * 60);
  const cost = () => (rand() < 0.15 ? 1000000 : 1 + Math.floor(rand() * 25));
  return [total, cost(), cost()];
}
